(4318360, 622568, 72268, '<td valign="top">Don''t get how it applies to buying on ebay.</td>', 'Don''t get how it applies to buying on ebay.', '2007-12-17 09:28:46.000000', NULL, 1),
(4318361, 622616, 85886, '<td valign="top">Lovely shot.  I love the muted colours of the shop and her pink coat against a relatively simple palette.  I love the perspective - is this handheld?  How on earth did you manage to get such DoF in apparently covered/low lighting, and a pin sharp shot?  It''s a little stretch on the interpretation but it''s definitely relevant imho.  Lovely shot...well done!</td>', 'Lovely shot.  I love the muted colours of the shop and her pink coat against a relatively simple palette.  I love the perspective - is this handheld?  How on earth did you manage to get such DoF in apparently covered/low lighting, and a pin sharp shot?  It''s a little stretch on the interpretation but it''s definitely relevant imho.  Lovely shot...well done!', '2007-12-17 09:29:00.000000', NULL, 1),
(4318363, 621317, 72268, '<td valign="top">I want it. Looks like your dog does too!</td>', 'I want it. Looks like your dog does too!', '2007-12-17 09:29:15.000000', NULL, 1),
(4318365, 623079, 72268, '<td valign="top">This has to be lovethelight!</td>', 'This has to be lovethelight!', '2007-12-17 09:29:56.000000', NULL, 1),
