(4320650, 622143, 3746, '<td valign="top">LOL, very good, one of the funnier entries. Good idea and not just some item shoehorned in.. 8 hope it does well for you.</td>', 'LOL, very good, one of the funnier entries. Good idea and not just some item shoehorned in.. 8 hope it does well for you.', '2007-12-18 15:12:41.000000', NULL, 1),
(4320655, 621317, 3746, '<td valign="top">The Nikon users are gonna crucify you for this.. but us 5D users must stick together!!<br/> <br/>Seriously though, nicely staged, the dog is a nice touch. Also appreciate the little details on the wall.</td>', 'The Nikon users are gonna crucify you for this.. but us 5D users must stick together!! Seriously though, nicely staged, the dog is a nice touch. Also appreciate the little details on the wall.', '2007-12-18 15:13:56.000000', NULL, 1),
