(4320659, 623128, 3746, '<td valign="top">shoehorned.. not bad photo though.</td>', 'shoehorned.. not bad photo though.', '2007-12-18 15:15:12.000000', NULL, 1),
(4320660, 623039, 63269, '<td valign="top">The picture is sort of at an odd angle... I personally would suggest either straightening it out so the ''horizon'' is straight. Or you could go all the way and experiment with some really crazy angles to make this look more interesting. Hope that was helpful! :)</td>', 'The picture is sort of at an odd angle... I personally would suggest either straightening it out so the ''horizon'' is straight. Or you could go all the way and experiment with some really crazy angles to make this look more interesting. Hope that was helpful! :)', '2007-12-18 15:15:40.000000', NULL, 1),
(4320662, 623111, 63269, '<td valign="top">Very nice abstract - the colors, lighting, and focus are great.</td>', 'Very nice abstract - the colors, lighting, and focus are great.', '2007-12-18 15:16:00.000000', NULL, 1),
