INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4327154, 623137, 67697, '<td valign="top">I need to learn how to make pictures look like this.  Awesome job. Love the tree. Good luck!</td>', 'I need to learn how to make pictures look like this.  Awesome job. Love the tree. Good luck!', '2007-12-20 23:04:35.000000', NULL, 1),
(4327158, 623119, 67697, '<td valign="top">You really did create a soft vintage look here - very nice.  It also looks like a photo that someone might actually post on ebay.  Good luck!</td>', 'You really did create a soft vintage look here - very nice.  It also looks like a photo that someone might actually post on ebay.  Good luck!', '2007-12-20 23:05:25.000000', NULL, 1),
(4327160, 622618, 67697, '<td valign="top">Isn''t that the truth?  Ebay is fuel for addiction for sure.  Love the light and shadows - very cool.</td>', 'Isn''t that the truth?  Ebay is fuel for addiction for sure.  Love the light and shadows - very cool.', '2007-12-20 23:06:22.000000', NULL, 1),
(4327163, 623113, 67697, '<td valign="top">Heh - funny! Love the spelling - that''s a sure sign of an ebay scam-meister. Hope people get it.  Good luck!</td>', 'Heh - funny! Love the spelling - that''s a sure sign of an ebay scam-meister. Hope people get it.  Good luck!', '2007-12-20 23:08:02.000000', NULL, 1),
(4327168, 622779, 60862, '<td valign="top">Ah, excellent!  Love the concept, composition, and processing.</td>', 'Ah, excellent!  Love the concept, composition, and processing.', '2007-12-20 23:10:12.000000', NULL, 1),
(4327170, 622738, 67697, '<td valign="top">I don''t know why, but this just cracks me up.  A boulder is about the only origami thing I could ever create.  omg - ok I had to go see if this was actually a website.  LOL.  damn i want to know if they make any money.  Thanks for the great laugh.</td>', 'I don''t know why, but this just cracks me up.  A boulder is about the only origami thing I could ever create.  omg - ok I had to go see if this was actually a website.  LOL.  damn i want to know if they make any money.  Thanks for the great laugh.', '2007-12-20 23:10:25.000000', NULL, 1),
(4327172, 621317, 60862, '<td valign="top">Congrats!  I''d say you''re showing exactly the right move.  Why sit on a computer with that baby arriving? :)  The dog adds a Norman Rockwell-like quality to the shot.</td>', 'Congrats!  I''d say you''re showing exactly the right move.  Why sit on a computer with that baby arriving? :)  The dog adds a Norman Rockwell-like quality to the shot.', '2007-12-20 23:10:43.000000', NULL, 1),
(4327173, 622143, 60862, '<td valign="top">Ha!  I hope this does well.  You''ve captured so much of the eBay experience:  something you probably won''t use, and it might not live up to the hype, but it''s cheap! :)</td>', 'Ha!  I hope this does well.  You''ve captured so much of the eBay experience:  something you probably won''t use, and it might not live up to the hype, but it''s cheap! :)', '2007-12-20 23:10:58.000000', NULL, 1),
